#!/usr/bin/env python3
"""Build the final HTML report embedding all generated charts."""

import json
import pandas as pd
import numpy as np

# Load chart data
with open('/app/output/charts_metadata.json', 'r') as f:
    charts = json.load(f)

# Load raw data for inline stats
df = pd.read_csv('/app/benchmark/data.csv')

# Compute KPIs and stats
total = len(df)
yearly = df.groupby('pub_year').size().to_dict()
oa_rate = df['open_access'].mean() * 100
oa_by_year = (df.groupby('pub_year')['open_access'].mean() * 100).to_dict()
median_authors = df['authors_count'].median()
mean_authors = df['authors_count'].mean()

country_fix = {
    'United States': 'USA', 'United States of America': 'USA',
    'PR China': 'China', "People's Republic of China": 'China',
    'Republic of Korea': 'South Korea', 'P R China': 'China',
}
df['country_clean'] = df['country'].replace(country_fix)
top10_share = df['country_clean'].value_counts().head(10).sum() / total * 100

# Research types
def get_primary_type(rt):
    if pd.isna(rt) or rt == '':
        return 'Other'
    types = [t.strip() for t in str(rt).split(';')]
    for t in ['Systematic Review', 'Review', 'Case Reports', 'Preprint',
